// Normalize inbound payload and build Scorpion-compatible register body
// Scorpion /api/services/register requires:
//   serviceName (string, min 1)
//   version (string, min 1)
//   host (string, min 1)
//   port (number, int, 1-65535)
//   protocol (enum: 'http' | 'https' | 'grpc')
//   status? ('healthy' | 'unhealthy' | 'unknown')
//   metadata? (Record<string, string>)
//   tags? (string[])
const body = $json.body || $json;

const serviceName = body.serviceName || body.service_name || body.name || 'hive-golden-path-smoke';
const version = body.version || body.ver || '1.0.0';
const host = body.host || body.hostname || 'evenslouis.ca';
const port = Number(body.port) || 443;
const protocol = body.protocol || 'https';
const status = body.status || 'healthy';

const metadata = {
  correlationId: body.correlationId || body.correlation_id || `gp_${Date.now()}`,
  source: body.source || 'hive-golden-path',
  goal: body.goal || 'smoke-test-registration',
  summary: body.summary || `Golden path smoke from ${serviceName}`,
  jobType: body.jobType || body.job_type || 'maintenance',
  triggeredAt: new Date().toISOString()
};

const tags = body.tags || ['hive', 'golden-path', 'smoke-test'];

return [{
  json: {
    registerPayload: {
      serviceName,
      version,
      host,
      port,
      protocol,
      status,
      metadata,
      tags
    },
    originalInput: body
  }
}];

// Evaluate registration result
const result = $input.first().json;
const statusCode = result.statusCode || result.code || 200;
const success = statusCode >= 200 && statusCode < 300;

if (!success) {
  return [{
    json: {
      registered: false,
      statusCode,
      error: result.message || result.error || 'Registration failed',
      hint: 'Check payload shape matches Scorpion /api/services/register Zod schema: serviceName, version, host, port (int), protocol (http|https|grpc).',
      sentPayload: $('Build Register Payload').first().json.registerPayload
    }
  }];
}

return [{
  json: {
    registered: true,
    serviceId: result.data?.id || result.id || null,
    message: result.data?.message || result.message || 'OK'
  }
}];
